import subprocess,sys,tempfile
root=Path(__file__).resolve().parents[2]; source=Path(sys.argv[1]) if len(sys.argv)==2 else root/'macos-native/Sources/VEXNativeMac/Stores/VEXAppState.swift'; source=source/'macos-native/Sources/VEXNativeMac/Stores/VEXAppState.swift' if source.is_dir() else source; s=source.read_text()
def ext(mark):
 a=s.index(mark); b=s.index('{',a); n=1; i=b+1
 while n: n+=(s[i]=='{')-(s[i]=='}'); i+=1
 return s[a:i]
prepared=ext('    private func connectPreparedTunnel(').replace('private func connectPreparedTunnel','func connectPreparedTunnel',1)
if 'sessionGeneration: Int? = nil' not in prepared:
 prepared += '''\n    func connectPreparedTunnel(_ tunnel: PreparedTunnel, helper: Helper, generation: Int, resiliencePolicy: ResiliencePolicy? = nil, sessionGeneration: Int? = nil, accessToken token: String? = nil, accountID: String? = nil) async throws -> PreparedTunnel { try await connectPreparedTunnel(tunnel, helper: helper, generation: generation, resiliencePolicy: resiliencePolicy) }\n'''
